import "server-only";
import createClient from "openapi-fetch";
import type { components, paths } from "./api-schema";

export type Panel = components["schemas"]["Panel"];
export type ErrorApi = components["schemas"]["ErrorApi"];

/**
 * Cliente del BFF. Corre solo en el servidor de Next.js: la URL y el token
 * se leen en tiempo de ejecución (Cloud Run los inyecta), nunca en el build.
 */
export function clienteBff() {
  const baseUrl = process.env.API_URL;
  if (!baseUrl) throw new Error("Falta API_URL en el entorno del servidor.");
  return createClient<paths>({
    baseUrl,
    headers: { "X-TraderPulse-Token": process.env.TRADERPULSE_TOKEN ?? "" },
  });
}

export type ResultadoPanel =
  | { ok: true; panel: Panel }
  | { ok: false; estado: number; error: ErrorApi };

export async function cargarPanel(simbolo: string): Promise<ResultadoPanel> {
  const { data, error, response } = await clienteBff().GET("/api/v1/panel/{simbolo}", {
    params: { path: { simbolo } },
    cache: "no-store",
  });
  if (data) return { ok: true, panel: data };
  // 401 y 404 traen ErrorApi; 422 trae el formato de validación de FastAPI.
  // El contrato obliga a distinguirlos: el compilador no deja leer "codigo" de un 422.
  const tipado = error && "codigo" in error ? error : null;
  return {
    ok: false,
    estado: response.status,
    error: tipado ?? { codigo: "error_bff", mensaje: `El BFF respondió ${response.status}.` },
  };
}

import { cargarPanel } from "@/lib/api";
import { cambio, precio, puntosSparkline } from "@/lib/formato";

const SUGERIDOS = ["AAPL", "MSFT", "NVDA", "GOOGL", "TSLA"];

type Props = { searchParams: Promise<{ simbolo?: string }> };

export default async function Inicio({ searchParams }: Props) {
  const { simbolo } = await searchParams;
  const resultado = simbolo ? await cargarPanel(simbolo) : null;

  return (
    <main>
      <h1>TraderPulse</h1>
      <p className="sub">Cotización, tendencia del mes y sentimiento de un símbolo. Datos de ejemplo.</p>

      <form action="/" method="get" role="search">
        <input
          name="simbolo"
          aria-label="Símbolo"
          placeholder="Escribe un símbolo, por ejemplo NVDA"
          defaultValue={simbolo ?? ""}
          maxLength={10}
          required
        />
        <button type="submit">Analizar</button>
      </form>

      {!resultado && (
        <nav className="chips" aria-label="Símbolos sugeridos">
          {SUGERIDOS.map((s) => (
            <a key={s} href={`/?simbolo=${s}`}>
              {s}
            </a>
          ))}
        </nav>
      )}

      {resultado && !resultado.ok && (
        <section className="tarjeta" role="alert">
          <p className="aviso">{resultado.error.mensaje}</p>
        </section>
      )}

      {resultado?.ok && <PanelSimbolo panel={resultado.panel} />}
    </main>
  );
}

function PanelSimbolo({ panel }: { panel: import("@/lib/api").Panel }) {
  const { cotizacion: c, historico, sentimiento: s } = panel;
  const tono = c.cambio_pct >= 0 ? "sube" : "baja";
  return (
    <>
      <section className="tarjeta" aria-label={`Cotización de ${c.simbolo}`}>
        <small>
          {c.simbolo} · {c.nombre} · cierre del {c.fecha}
        </small>
        <p className="precio" data-testid="precio">
          {precio(c.precio)}
        </p>
        <p className={tono} data-testid="cambio">
          {cambio(c.cambio_pct)} contra el cierre anterior
        </p>
        <svg width="100%" viewBox="0 0 320 80" role="img" aria-label="Cierres del último mes">
          <polyline
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
            points={puntosSparkline(historico.map((p) => p.cierre))}
          />
        </svg>
      </section>
      <section className="tarjeta" aria-label="Sentimiento">
        <span className="etiqueta" data-testid="sentimiento">
          {s.sentimiento}
        </span>
        <p>{s.justificacion}</p>
        <small>Fuente: {s.fuente}</small>
      </section>
    </>
  );
}

"""TraderPulse BFF. Cada ruta declara su respuesta y sus errores con un modelo tipado."""

import secrets
from importlib.metadata import version

from fastapi import Depends, FastAPI, Header, Query
from fastapi.responses import JSONResponse

from . import mercado, sentimiento
from .config import ajustes
from .modelos import (
    AnalisisSentimiento,
    Cotizacion,
    ErrorApi,
    Instrumento,
    Panel,
    PuntoHistorico,
    Salud,
)

VERSION = version("traderpulse-api")


class ErrorDeApi(Exception):
    def __init__(self, estado: int, codigo: str, mensaje: str):
        self.estado, self.codigo, self.mensaje = estado, codigo, mensaje


def verificar_token(x_traderpulse_token: str = Header(default="")) -> None:
    esperado = ajustes().traderpulse_token
    if esperado and not secrets.compare_digest(x_traderpulse_token, esperado):
        raise ErrorDeApi(401, "token_invalido", "Falta el token del frontend o no coincide.")


def simbolo_valido(simbolo: str) -> str:
    if not mercado.existe(simbolo):
        raise ErrorDeApi(404, "simbolo_desconocido", f"No hay datos para '{simbolo}'.")
    return mercado.normalizar(simbolo)


ERRORES = {
    401: {"model": ErrorApi, "description": "Token ausente o incorrecto."},
    404: {"model": ErrorApi, "description": "El símbolo no existe."},
}

app = FastAPI(
    title="TraderPulse BFF",
    version=VERSION,
    description="API que sirve a la pantalla de TraderPulse. Datos de mercado de ejemplo.",
)


@app.exception_handler(ErrorDeApi)
async def _error_de_api(_, exc: ErrorDeApi) -> JSONResponse:
    cuerpo = ErrorApi(codigo=exc.codigo, mensaje=exc.mensaje)
    return JSONResponse(status_code=exc.estado, content=cuerpo.model_dump())


@app.get("/salud", response_model=Salud, operation_id="salud", tags=["sistema"])
def salud() -> Salud:
    return Salud(version=VERSION)


api = [Depends(verificar_token)]


@app.get(
    "/api/v1/instrumentos",
    response_model=list[Instrumento],
    responses={401: ERRORES[401]},
    operation_id="buscarInstrumentos",
    dependencies=api,
    tags=["mercado"],
)
def buscar_instrumentos(q: str = Query(default="", max_length=40)) -> list[Instrumento]:
    return mercado.buscar(q)


@app.get(
    "/api/v1/panel/{simbolo}",
    response_model=Panel,
    responses=ERRORES,
    operation_id="panel",
    dependencies=api,
    tags=["pantalla"],
)
def panel(simbolo: str = Depends(simbolo_valido)) -> Panel:
    return Panel(
        cotizacion=mercado.cotizacion(simbolo),
        historico=mercado.historico(simbolo),
        sentimiento=sentimiento.analizar(simbolo),
    )


@app.get(
    "/api/v1/cotizaciones/{simbolo}",
    response_model=Cotizacion,
    responses=ERRORES,
    operation_id="cotizacion",
    dependencies=api,
    tags=["mercado"],
)
def obtener_cotizacion(simbolo: str = Depends(simbolo_valido)) -> Cotizacion:
    return mercado.cotizacion(simbolo)


@app.get(
    "/api/v1/historico/{simbolo}",
    response_model=list[PuntoHistorico],
    responses=ERRORES,
    operation_id="historico",
    dependencies=api,
    tags=["mercado"],
)
def obtener_historico(simbolo: str = Depends(simbolo_valido)) -> list[PuntoHistorico]:
    return mercado.historico(simbolo)


@app.get(
    "/api/v1/sentimiento/{simbolo}",
    response_model=AnalisisSentimiento,
    responses=ERRORES,
    operation_id="sentimiento",
    dependencies=api,
    tags=["mercado"],
)
def obtener_sentimiento(simbolo: str = Depends(simbolo_valido)) -> AnalisisSentimiento:
    return sentimiento.analizar(simbolo)
